SET VERIFY OFF ECHO OFF
WHENEVER SQLERROR EXIT FAILURE
ALTER SESSION SET CONTAINER=FREEPDB1;
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM dba_users WHERE username='ALUMNO';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE USER alumno IDENTIFIED BY "&&app_pwd" DEFAULT TABLESPACE USERS QUOTA 100M ON USERS';
    EXECUTE IMMEDIATE 'GRANT DB_DEVELOPER_ROLE, CREATE SESSION TO alumno';
  END IF;
END;
/
BEGIN
  ORDS_ADMIN.ENABLE_SCHEMA(p_enabled=>TRUE,p_schema=>'ALUMNO',p_url_mapping_type=>'BASE_PATH',p_url_mapping_pattern=>'alumno',p_auto_rest_auth=>TRUE);
  COMMIT;
END;
/
SELECT username,account_status,default_tablespace FROM dba_users WHERE username='ALUMNO';
EXIT
